input.command:
THREAD_ID=$(gh api graphql -f query='
{
  repository(owner: "LAF-US", name: "IDAHO-VAULT") {
    pullRequest(number: 556) {
      reviewThreads(first: 50) {
        nodes { id isResolved comments(first: 1) { nodes { databaseId } } }
      }
    }
  }
}' --jq '.data.repository.pullRequest.reviewThreads.nodes[] | select(.comments.nodes[0].databaseId==3431572552) | .id')
echo "thread: $THREAD_ID"
gh api graphql -f query="mutation { resolveReviewThread(input: {threadId: \"$THREAD_ID\"}) { thread { isResolved } } }" 2>&1 | tail -3
